// Generated by scripts/generate-maps-browser-config.js during Netlify builds.
//
// A Maps JavaScript API browser key is public by design: the browser must send
// it to Google. Security comes from using a dedicated key restricted in GCP to
// the approved website origins and to the Maps JavaScript/Directions APIs.
// The committed null value keeps local/static checkouts fail-closed and keeps
// the real key out of Git history.
window.LINKMIA_MAPS_CONFIG = Object.freeze({ apiKey: null });
